package com.vcube.stockwise.service;

import com.fasterxml.jackson.databind.*;
import com.vcube.stockwise.domain.*;
import com.vcube.stockwise.repo.*;
import org.springframework.ai.chat.client.ChatClient;
import org.springframework.ai.chat.model.ChatModel;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.beans.factory.ObjectProvider;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

@Service public class AiService {
 private static final Logger log=LoggerFactory.getLogger(AiService.class);
 private final ProductRepository products;private final SupplierRepository suppliers;private final StockTransactionRepository transactions;private final PurchaseOrderRepository orders;private final ObjectMapper json;private final ChatClient chatClient;private final boolean aiConfigured;
 public AiService(ProductRepository products,SupplierRepository suppliers,StockTransactionRepository transactions,PurchaseOrderRepository orders,ObjectMapper json,ObjectProvider<ChatModel> chatModelProvider,@Value("${spring.ai.openai.api-key:}") String apiKey){this.products=products;this.suppliers=suppliers;this.transactions=transactions;this.orders=orders;this.json=json;ChatModel chatModel=chatModelProvider.getIfAvailable();this.chatClient=chatModel==null?null:ChatClient.create(chatModel);this.aiConfigured=apiKey!=null&&!apiKey.isBlank()&&this.chatClient!=null;}

 public Map<String,Object> forecast(Long productId){Product p=products.findById(productId).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Product not found"));Instant since=Instant.now().minus(30,ChronoUnit.DAYS);List<StockTransaction> outs=transactions.findByProduct_IdAndTypeAndTransactionDateAfter(productId,"STOCK_OUT",since);long sold=outs.stream().mapToLong(StockTransaction::getQuantity).sum();Map<String,Object> history=new TreeMap<>();for(var tx:outs){String week=tx.getTransactionDate().atZone(ZoneOffset.UTC).toLocalDate().toString();history.merge(week,tx.getQuantity(),(a,b)->(Integer)a+(Integer)b);}double daily=sold/30.0;double lead=p.getSupplier()==null?7:p.getSupplier().getLeadTimeDays();Map<String,Object> context=Map.of("product",Map.of("id",p.getId(),"sku",p.getSku(),"name",p.getName(),"category",p.getCategory(),"currentStock",p.getCurrentStock(),"reorderLevel",p.getReorderLevel(),"optimalStockLevel",p.getOptimalStockLevel(),"unitPrice",p.getUnitPrice(),"costPrice",p.getCostPrice(),"supplierLeadTimeDays",lead),"stockOutHistoryLast30Days",history,"stockOutUnitsLast30Days",sold);
  int d7=(int)Math.ceil(daily*7),d14=(int)Math.ceil(daily*14),d30=(int)Math.ceil(daily*30);Object stockout=daily>0&&p.getCurrentStock()/daily<=30?LocalDate.now(ZoneOffset.UTC).plusDays((long)Math.ceil(p.getCurrentStock()/daily)).toString():"not expected within 30 days";Map<String,Object> fallback=new LinkedHashMap<>();fallback.put("productId",p.getId());fallback.put("sku",p.getSku());fallback.put("productName",p.getName());fallback.put("forecast",Map.of("demandNext7Days",d7,"demandNext14Days",d14,"demandNext30Days",d30,"predictedStockoutDate",stockout,"trendNotes",trendNote(history),"recommendedAction",p.getCurrentStock()<=p.getReorderLevel()?"Replenish soon":"Monitor stock velocity","confidence",outs.size()<3?"low":"baseline"));fallback.put("dataContext",context);
  String prompt="Forecast inventory demand. Return one JSON object with productId, sku, productName, and forecast {demandNext7Days integer, demandNext14Days integer, demandNext30Days integer, predictedStockoutDate ISO date or string 'not expected within 30 days', trendNotes, recommendedAction, confidence}. Forecast only from this live database context and note that 30 days of history is limited for seasonality. Context JSON: "+toJson(context);Map<String,Object> answer=completeJson(prompt,fallback);return withMeta(answer);
 }

 public Map<String,Object> optimize(){List<Product> all=products.findAll();Instant since=Instant.now().minus(30,ChronoUnit.DAYS);List<StockTransaction> outs=transactions.findByTypeAndTransactionDateAfter("STOCK_OUT",since);List<Map<String,Object>> context=all.stream().map(p->{long sold=outs.stream().filter(t->t.getProductId().equals(p.getId())).mapToLong(StockTransaction::getQuantity).sum();int lead=p.getSupplier()==null?7:p.getSupplier().getLeadTimeDays();double daily=sold/30.0;int reorder=Math.max(1,(int)Math.ceil(daily*(lead+3)));int optimal=Math.max(reorder,(int)Math.ceil(daily*(lead+14)));Map<String,Object> row=new LinkedHashMap<>();row.put("productId",p.getId());row.put("sku",p.getSku());row.put("name",p.getName());row.put("currentStock",p.getCurrentStock());row.put("currentReorderLevel",p.getReorderLevel());row.put("currentOptimalStockLevel",p.getOptimalStockLevel());row.put("stockOutLast30Days",sold);row.put("dailyVelocity",daily);row.put("costPrice",p.getCostPrice());row.put("supplierLeadTimeDays",lead);row.put("heuristicReorderLevel",reorder);row.put("heuristicOptimalStockLevel",optimal);return row;}).toList();List<Map<String,Object>> fallback=new ArrayList<>();for(var row:context){Map<String,Object> rec=new LinkedHashMap<>();rec.put("productId",row.get("productId"));rec.put("sku",row.get("sku"));rec.put("productName",row.get("name"));rec.put("recommendedReorderLevel",row.get("heuristicReorderLevel"));rec.put("recommendedOptimalStockLevel",row.get("heuristicOptimalStockLevel"));rec.put("reason","Calculated from recent stock-out velocity, carrying cost, and supplier lead time.");fallback.add(rec);}Map<String,Object> defaults=Map.of("recommendations",fallback,"method","velocity and lead-time baseline","context",context);String prompt="Review each product's recent demand, current stock, unit cost, and supplier lead time. Return JSON {recommendations:[{productId,sku,productName,recommendedReorderLevel integer,recommendedOptimalStockLevel integer,reason}]}. Keep recommended optimal level >= reorder level; avoid overstocking slow movers; do not invent products. Context JSON: "+toJson(context);Map<String,Object> result=completeJson(prompt,defaults);result.put("context",context);return withMeta(result);}

 public Map<String,Object> purchaseRecommendations(){List<Product> all=products.findAll();List<Map<String,Object>> context=new ArrayList<>();Map<Long,Product> byId=new HashMap<>();for(Product p:all){long sold=transactions.findByProduct_IdAndTypeAndTransactionDateAfter(p.getId(),"STOCK_OUT",Instant.now().minus(30,ChronoUnit.DAYS)).stream().mapToLong(StockTransaction::getQuantity).sum();int lead=p.getSupplier()==null?7:p.getSupplier().getLeadTimeDays();double daily=sold/30.0;double daysCover=daily==0?Double.POSITIVE_INFINITY:p.getCurrentStock()/daily;int quantity=Math.max(0,p.getOptimalStockLevel()-p.getCurrentStock());boolean candidate=p.getCurrentStock()<=p.getReorderLevel()||daysCover<=lead;if(!candidate)continue;if(quantity==0)quantity=Math.max(1,(int)Math.ceil(daily*(lead+14)-p.getCurrentStock()));if(p.getSupplier()==null)continue;byId.put(p.getId(),p);Map<String,Object> row=new LinkedHashMap<>();row.put("productId",p.getId());row.put("sku",p.getSku());row.put("productName",p.getName());row.put("currentStock",p.getCurrentStock());row.put("reorderLevel",p.getReorderLevel());row.put("optimalStockLevel",p.getOptimalStockLevel());row.put("stockOutLast30Days",sold);row.put("supplierId",p.getSupplier().getId());row.put("supplierName",p.getSupplier().getName());row.put("supplierLeadTimeDays",lead);row.put("suggestedQuantity",quantity);row.put("unitCost",p.getCostPrice());context.add(row);}
  Map<Long,List<Map<String,Object>>> grouped=new LinkedHashMap<>();for(var c:context){@SuppressWarnings("unchecked") Map<String,Object> line=new LinkedHashMap<>();line.put("productId",c.get("productId"));line.put("sku",c.get("sku"));line.put("productName",c.get("productName"));line.put("quantity",c.get("suggestedQuantity"));line.put("unitCost",c.get("unitCost"));grouped.computeIfAbsent((Long)c.get("supplierId"),k->new ArrayList<>()).add(line);}
  List<Map<String,Object>> drafts=new ArrayList<>();for(var entry:grouped.entrySet()){Product p=byId.get((Long)entry.getValue().get(0).get("productId"));var supplier=p.getSupplier();Map<String,Object> draft=new LinkedHashMap<>();draft.put("supplierId",supplier.getId());draft.put("supplierName",supplier.getName());draft.put("expectedDeliveryDate",LocalDate.now().plusDays(supplier.getLeadTimeDays()).toString());draft.put("items",entry.getValue());draft.put("totalAmount",entry.getValue().stream().mapToDouble(line->((Number)line.get("quantity")).doubleValue()*((java.math.BigDecimal)line.get("unitCost")).doubleValue()).sum());drafts.add(draft);}
  Map<String,Object> fallback=Map.of("draftPurchaseOrders",drafts,"context",context);String prompt="From live candidate rows, prepare actionable draft purchase orders grouped by the preferred existing supplier. Return JSON {draftPurchaseOrders:[{supplierId,supplierName,expectedDeliveryDate ISO date,items:[{productId,sku,productName,quantity integer,unitCost}],reason}]}. Use only provided IDs and suggested quantities, and include exact supplier lead time. Context JSON: "+toJson(context);Map<String,Object> result=completeJson(prompt,fallback);result.put("context",context);return withMeta(result);
 }

 public Map<String,Object> chat(String question){String q=question==null?"":question.trim();if(q.isBlank())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Question is required");Instant since=Instant.now().minus(30,ChronoUnit.DAYS);List<Product> inventory=products.findAll();List<StockTransaction> movements=transactions.findByTransactionDateAfterOrderByTransactionDateAsc(since);List<PurchaseOrder> allOrders=orders.findAll();long outs=movements.stream().filter(t->t.getType().equals("STOCK_OUT")).mapToLong(StockTransaction::getQuantity).sum();var low=inventory.stream().filter(p->p.getCurrentStock()<=p.getReorderLevel()).toList();var overdue=allOrders.stream().filter(po->po.getExpectedDeliveryDate()!=null&&po.getExpectedDeliveryDate().isBefore(LocalDate.now())&&!Set.of("RECEIVED","CANCELLED").contains(po.getStatus())).toList();var top=inventory.stream().sorted(Comparator.comparingLong(Product::getSoldLast30Days).reversed()).limit(5).map(p->Map.of("name",p.getName(),"unitsSold30d",p.getSoldLast30Days(),"salesValue",p.getUnitPrice().multiply(java.math.BigDecimal.valueOf(p.getSoldLast30Days())))).toList();Map<String,Object> context=new LinkedHashMap<>();context.put("productCount",inventory.size());context.put("inventoryValueAtCost",inventory.stream().mapToDouble(p->p.getCostPrice().doubleValue()*p.getCurrentStock()).sum());context.put("lowStock",low.stream().map(p->Map.of("sku",p.getSku(),"name",p.getName(),"stock",p.getCurrentStock(),"reorderLevel",p.getReorderLevel(),"sold30d",p.getSoldLast30Days())).toList());context.put("stockOutUnits30d",outs);context.put("pendingPurchaseOrders",allOrders.stream().filter(p->Set.of("PENDING","APPROVED","ORDERED").contains(p.getStatus())).count());context.put("overduePurchaseOrders",overdue.stream().map(p->Map.of("poNumber",p.getPoNumber(),"supplier",p.getSupplierName(),"expectedDeliveryDate",p.getExpectedDeliveryDate().toString(),"status",p.getStatus())).toList());context.put("topRevenueProducts",top);context.put("suppliers",suppliers.findAll().stream().map(s->Map.of("id",s.getId(),"name",s.getName(),"leadTimeDays",s.getLeadTimeDays(),"rating",s.getRating())).toList());Map<String,Object> fallback=Map.of("answer",fallbackAnswer(q,context),"contextSummary",context);String prompt="Answer the user's inventory question using only the following live structured database summary. If data is not present, say what is missing; do not invent delay or sales figures. Return JSON {answer:string, contextSummary:short string}. User question: "+q+"\nDatabase context JSON: "+toJson(context);Map<String,Object> result=completeJson(prompt,fallback);result.put("contextSummary",context);return withMeta(result);}

 private String fallbackAnswer(String question,Map<String,Object> context){String q=question.toLowerCase(Locale.ROOT);if(q.contains("delay")||q.contains("late"))return "There are "+((List<?>)context.get("overduePurchaseOrders")).size()+" purchase orders past their expected delivery date.";if(q.contains("revenue")||q.contains("top"))return "Top revenue-generating products are ranked in the attached live context by 30-day units sold times unit price.";if(q.contains("reorder")||q.contains("buy")||q.contains("purchase"))return "There are "+((List<?>)context.get("lowStock")).size()+" items at or below reorder level. Use the Purchase Recommendations panel for draft quantities.";return "The inventory currently has "+context.get("productCount")+" products, "+((List<?>)context.get("lowStock")).size()+" low-stock items, and "+context.get("pendingPurchaseOrders")+" open purchase orders.";}
 private String trendNote(Map<String,Object> history){if(history.size()<3)return "Limited history; trend and seasonality confidence is low.";List<Integer> counts=history.values().stream().map(v->((Number)v).intValue()).toList();double first=counts.subList(0,counts.size()/2).stream().mapToInt(Integer::intValue).average().orElse(0),last=counts.subList(counts.size()/2,counts.size()).stream().mapToInt(Integer::intValue).average().orElse(0);return last>first*1.15?"Recent stock-out activity is increasing; seasonality cannot be established from one month.":last<first*.85?"Recent stock-out activity is easing; seasonality cannot be established from one month.":"Recent stock-out activity is broadly stable; one month is insufficient to establish seasonality.";}
 private Map<String,Object> completeJson(String prompt,Map<String,Object> fallback){
  if(!aiConfigured){Map<String,Object> result=new LinkedHashMap<>(fallback);result.put("source","RULE_BASED_FALLBACK");return result;}
  try {
   String raw=chatClient.prompt()
    .system("You are a careful inventory analyst. Use only supplied live database facts, return one valid JSON object without markdown, and identify uncertainty.")
    .user(prompt)
    .call()
    .content();
   if(raw==null||raw.isBlank())throw new IllegalStateException("Spring AI returned an empty response");
   String normalized=raw.trim().replaceAll("^```(?:json)?\\s*","").replaceAll("\\s*```$","");
   JsonNode root=json.readTree(normalized);
   if(!root.isObject())throw new IllegalStateException("Spring AI response is not a JSON object");
   Map<String,Object> result=json.convertValue(root,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});
   result.put("source","SPRING_AI_LIVE");
   return result;
  }catch(Exception ex){
   log.warn("Spring AI request failed; using live database fallback ({})",ex.getClass().getSimpleName());
   Map<String,Object> result=new LinkedHashMap<>(fallback);result.put("source","RULE_BASED_FALLBACK");return result;
  }
 }
 private String toJson(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("Could not serialize AI context",e);}}
 private Map<String,Object> withMeta(Map<String,Object> result){result.putIfAbsent("source","RULE_BASED_FALLBACK");result.put("generatedAt",Instant.now().toString());return result;}
}
